  for field in "${REQUIRED_TASK_FIELDS[@]}"; do
    if grep -q "$field" tasks/_template.md; then
      echo "  OK: tasks/_template.md → $field"
    else
      echo "  MISSING in tasks/_template.md: $field"
      ERRORS=$((ERRORS + 1))
    fi
  done
else
