#!/usr/bin/env bash
# =============================================================================
# TASK-0037: protect-sage-files.sh
# Purpose:  PreToolUse hook (Edit|Write matcher) — protect SAGE-managed files
# Profile:  standard+ (skipped if profile is "minimal" or "none")
# Behavior: Reads JSON from stdin with tool_name and tool_input.file_path.
#           Protected: CLAUDE.md, sage/*, .sage/config.yaml, .claude/settings.json
#           If a TASK with sage-managed: true AND status In Progress / 実行中 exists, allow.
#           Otherwise block (exit 2).
#           On empty stdin or parse error: exit 0
# =============================================================================
set -euo pipefail

# --- Profile gating ---
PROFILE="standard"
if [ -f ".sage/config.yaml" ]; then
  PROFILE=$(grep -A1 'hooks:' .sage/config.yaml 2>/dev/null | grep 'profile:' | awk '{print $2}' | tr -d '"' || echo "standard")
  [ -z "$PROFILE" ] && PROFILE="standard"
fi

if [ "$PROFILE" = "minimal" ] || [ "$PROFILE" = "none" ]; then
  exit 0
fi

task_status() {
  awk -F'|' '/^\|[[:space:]]*ステータス[[:space:]]*\|/ {gsub(/^[[:space:]]+|[[:space:]]+$/, "", $3); print $3; exit}' "$1" 2>/dev/null || true
}

task_is_active() {
  local status
  status="$(task_status "$1")"
  case "$status" in
    "In Progress"|"実行中")
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

# --- Read stdin (JSON) ---
INPUT=""
if ! read -r -t 1 INPUT; then
  exit 0
fi

if [ -z "$INPUT" ]; then
  exit 0
fi

# --- Parse file_path and content from JSON ---
FILE_PATH=""
CONTENT=""
if command -v jq &>/dev/null; then
  FILE_PATH=$(echo "$INPUT" | jq -r '.tool_input.file_path // empty' 2>/dev/null || true)
  # TASK-0104: also parse the write content for downstream hijack-pattern
  # detection. Falls back to empty when jq is unavailable; the path-only
  # check still runs in that case.
  CONTENT=$(echo "$INPUT" | jq -r '.tool_input.content // .tool_input.new_string // empty' 2>/dev/null || true)
else
  FILE_PATH=$(echo "$INPUT" | grep -o '"file_path"[[:space:]]*:[[:space:]]*"[^"]*"' 2>/dev/null | head -1 | sed 's/.*"file_path"[[:space:]]*:[[:space:]]*"//;s/"$//' || true)
fi

if [ -z "$FILE_PATH" ]; then
  exit 0
fi

# --- TASK-0104 (SPEC-0011) FR-05: hijack-pattern content check ---
# These checks run BEFORE the existing path/active-task gate so the hijack
# patterns are blocked even when an active sage-managed TASK exists.
# Background: cloned-repo trust attacks (Check Point CVE-2025-59536,
# CVE-2025-61260, NVD CVE-2026-33068) inject dangerous keys into config
# files that Claude Code / Codex CLI subsequently honor at trust time.

NORM_PATH_FOR_CONTENT="${FILE_PATH#./}"

content_contains() {
  # POSIX-grep regex against the parsed CONTENT.
  [ -n "$CONTENT" ] && echo "$CONTENT" | grep -qE "$1"
}

case "$NORM_PATH_FOR_CONTENT" in
  *.claude/settings.json|.claude/settings.json)
    if content_contains '"defaultMode"[[:space:]]*:[[:space:]]*"bypassPermissions"'; then
      echo "BLOCKED: '.claude/settings.json' write contains defaultMode=bypassPermissions." >&2
      echo "Reference: NVD CVE-2026-33068 (Claude Code trust dialog bypass)" >&2
      echo "  https://nvd.nist.gov/vuln/detail/CVE-2026-33068" >&2
      exit 2
    fi
    if content_contains '"enableAllProjectMcpServers"[[:space:]]*:[[:space:]]*true'; then
      echo "BLOCKED: '.claude/settings.json' write enables enableAllProjectMcpServers=true." >&2
      echo "Reference: Backslash Security Claude Code Best Practices (auto-trust of project MCP is high risk)" >&2
      exit 2
    fi
    ;;
  *.env|.env|*.env.local|.env.local|*.env.production|.env.production)
    if content_contains '^[[:space:]]*CODEX_HOME[[:space:]]*='; then
      echo "BLOCKED: '$NORM_PATH_FOR_CONTENT' write sets CODEX_HOME, which redirects Codex CLI config search." >&2
      echo "Reference: CVE-2025-61260 (Codex CLI project-local config RCE, fixed in 0.23.0)" >&2
      echo "  https://research.checkpoint.com/2025/openai-codex-cli-command-injection-vulnerability/" >&2
      exit 2
    fi
    if content_contains '^[[:space:]]*ANTHROPIC_BASE_URL[[:space:]]*='; then
      echo "BLOCKED: '$NORM_PATH_FOR_CONTENT' write sets ANTHROPIC_BASE_URL, which redirects Claude Code API traffic." >&2
      echo "Reference: CVE-2025-59536 (Claude Code project files RCE / API token exfil)" >&2
      echo "  https://research.checkpoint.com/2026/rce-and-api-token-exfiltration-through-claude-code-project-files-cve-2025-59536/" >&2
      exit 2
    fi
    ;;
  *.codex/config.toml|.codex/config.toml)
    if content_contains '^[[:space:]]*\[?mcp_servers\.|^[[:space:]]*mcp_servers[[:space:]]*='; then
      echo "BLOCKED: '.codex/config.toml' write defines mcp_servers — supply-chain risk per OWASP AST01-10." >&2
      echo "Reference: CVE-2025-61260 (project-local Codex config can launch unaudited MCP servers)" >&2
      echo "  https://research.checkpoint.com/2025/openai-codex-cli-command-injection-vulnerability/" >&2
      exit 2
    fi
    ;;
  *.mcp.json|.mcp.json)
    if content_contains '"mcpServers"[[:space:]]*:[[:space:]]*\{'; then
      echo "BLOCKED: '.mcp.json' write defines mcpServers — supply-chain risk per OWASP AST01-10." >&2
      echo "Reference: OWASP Agentic Skills Top 10 (AST01 Malicious Skills, AST02 Supply Chain)" >&2
      echo "  https://owasp.org/www-project-agentic-skills-top-10/" >&2
      exit 2
    fi
    ;;
esac

# --- Check if file is protected ---
IS_PROTECTED=false

# Normalize: strip leading ./ if present
NORM_PATH="${FILE_PATH#./}"

case "$NORM_PATH" in
  CLAUDE.md)
    IS_PROTECTED=true
    ;;
  sage/*)
    IS_PROTECTED=true
    ;;
  .sage/config.yaml)
    IS_PROTECTED=true
    ;;
  .claude/settings.json)
    IS_PROTECTED=true
    ;;
esac

# Also check if the path ends with these (for absolute paths)
if [ "$IS_PROTECTED" = false ]; then
  case "$FILE_PATH" in
    */CLAUDE.md)
      IS_PROTECTED=true
      ;;
    */sage/*)
      IS_PROTECTED=true
      ;;
    */.sage/config.yaml)
      IS_PROTECTED=true
      ;;
    */.claude/settings.json)
      IS_PROTECTED=true
      ;;
  esac
fi

if [ "$IS_PROTECTED" = false ]; then
  # Not a protected file — allow
  exit 0
fi

# --- Check for active sage-managed TASK ---
if [ -d "tasks" ]; then
  for task_file in tasks/*.md; do
    [ -f "$task_file" ] || continue

    # Check if task has sage-managed: true AND active status
    HAS_SAGE_MANAGED=false
    HAS_ACTIVE_STATUS=false

    if grep -q 'sage-managed:[[:space:]]*true' "$task_file" 2>/dev/null; then
      HAS_SAGE_MANAGED=true
    fi

    if task_is_active "$task_file"; then
      HAS_ACTIVE_STATUS=true
    fi

    if [ "$HAS_SAGE_MANAGED" = true ] && [ "$HAS_ACTIVE_STATUS" = true ]; then
      # Active sage-managed task found — allow edit
      exit 0
    fi
  done
fi

# --- Block: no active sage-managed task ---
echo "BLOCKED: '$NORM_PATH' is a SAGE-protected file." >&2
echo "Protected files: CLAUDE.md, sage/*, .sage/config.yaml, .claude/settings.json" >&2
echo "To modify, ensure a TASK in tasks/ has 'sage-managed: true' and status 'In Progress' (or '実行中')." >&2
exit 2

__EOF_TMPL_HOOK_PROTECT_SAGE__

read -r -d '' TMPL_HOOK_CHECK_SCOPE <<'__EOF_TMPL_HOOK_CHECK_SCOPE__' || true
#!/usr/bin/env bash
# =============================================================================
# TASK-0038: check-file-scope.sh
# Purpose:  PreToolUse hook (Edit|Write matcher) — enforce TASK File Scope
# Profile:  standard+ (warn on stderr, exit 0), strict (block with exit 2)
# Behavior: Reads JSON from stdin with tool_input.file_path.
#           Finds active TASKs (status In Progress / 実行中 in tasks/*.md), extracts File Scope.
#           If file_path is outside scope: warn (standard) or block (strict).
#           If no active TASK found: skip check, exit 0.
#           On empty stdin or parse error: exit 0
# =============================================================================
set -euo pipefail

# --- Profile gating ---
PROFILE="standard"
if [ -f ".sage/config.yaml" ]; then
  PROFILE=$(grep -A1 'hooks:' .sage/config.yaml 2>/dev/null | grep 'profile:' | awk '{print $2}' | tr -d '"' || echo "standard")
  [ -z "$PROFILE" ] && PROFILE="standard"
fi

if [ "$PROFILE" = "minimal" ] || [ "$PROFILE" = "none" ]; then
  exit 0
fi

task_status() {
  awk -F'|' '/^\|[[:space:]]*ステータス[[:space:]]*\|/ {gsub(/^[[:space:]]+|[[:space:]]+$/, "", $3); print $3; exit}' "$1" 2>/dev/null || true
}

task_is_active() {
  local status
  status="$(task_status "$1")"
  case "$status" in
    "In Progress"|"実行中")
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

append_scope_from_task() {
  local task_file="$1"
  local in_scope=false

  while IFS= read -r line; do
    if echo "$line" | grep -qiE '^#{1,3}\s+file.?scope'; then
      in_scope=true
      continue
    fi

    if [ "$in_scope" = true ] && echo "$line" | grep -qE '^#{1,3}\s+'; then
      break
    fi

    if [ "$in_scope" = true ]; then
      local item extracted
      item=$(echo "$line" | sed -n 's/^[[:space:]]*[-*][[:space:]]*//p' 2>/dev/null || true)
      [ -z "$item" ] && continue

      extracted=$(echo "$item" | sed -E 's/^[^:]+:[[:space:]]*//' | tr -d '`' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//' || true)
      case "$extracted" in
        ""|"[パス]"|"[path]")
          continue
          ;;
      esac
      SCOPE_PATHS+=("$extracted")
    fi
  done < "$task_file"
}

# --- Read stdin (JSON) ---
INPUT=""
if ! read -r -t 1 INPUT; then
  exit 0
fi

if [ -z "$INPUT" ]; then
  exit 0
fi

# --- Parse file_path from JSON ---
FILE_PATH=""
if command -v jq &>/dev/null; then
  FILE_PATH=$(echo "$INPUT" | jq -r '.tool_input.file_path // empty' 2>/dev/null || true)
else
  FILE_PATH=$(echo "$INPUT" | grep -o '"file_path"[[:space:]]*:[[:space:]]*"[^"]*"' 2>/dev/null | head -1 | sed 's/.*"file_path"[[:space:]]*:[[:space:]]*"//;s/"$//' || true)
fi

if [ -z "$FILE_PATH" ]; then
  exit 0
fi

# --- Find active TASKs (status In Progress / 実行中) ---
ACTIVE_TASKS=()
SCOPE_PATHS=()

if [ ! -d "tasks" ]; then
  echo "No active TASKs found, skipping scope check." >&2
  exit 0
fi

for task_file in tasks/*.md; do
  [ -f "$task_file" ] || continue

  if task_is_active "$task_file"; then
    ACTIVE_TASKS+=("$task_file")
  fi
done

if [ "${#ACTIVE_TASKS[@]}" -eq 0 ]; then
  echo "No active TASK found, skipping scope check." >&2
  exit 0
fi

for active_task in "${ACTIVE_TASKS[@]}"; do
  append_scope_from_task "$active_task"
done

if [ "${#SCOPE_PATHS[@]}" -eq 0 ]; then
  # No File Scope defined in TASK — skip check
  exit 0
fi

# --- Check if file_path falls within any scope path ---
# Normalize file_path: strip leading ./
NORM_PATH="${FILE_PATH#./}"

# Also handle absolute paths by extracting relative portion
if [[ "$NORM_PATH" == /* ]]; then
  # Try to make it relative to PWD
  PWD_PREFIX="$(pwd)/"
  NORM_PATH="${NORM_PATH#$PWD_PREFIX}"
fi

for scope_path in "${SCOPE_PATHS[@]}"; do
  [ -z "$scope_path" ] && continue

  if [[ "$scope_path" == */ ]]; then
    if [[ "$NORM_PATH" == "$scope_path"* ]]; then
      exit 0
    fi
  elif [[ "$NORM_PATH" == "$scope_path" ]] || [[ "$NORM_PATH" == "$scope_path/"* ]]; then
    exit 0
  fi
done

# --- Out of scope ---
TASK_IDS=()
for active_task in "${ACTIVE_TASKS[@]}"; do
  TASK_IDS+=("$(basename "$active_task" .md)")
done
TASK_LABEL=$(IFS=', '; echo "${TASK_IDS[*]}")
ALLOWED_PATHS=$(printf '%s\n' "${SCOPE_PATHS[@]}" | awk 'NF && !seen[$0]++' | paste -sd ', ' -)

if [ "$PROFILE" = "strict" ]; then
  echo "BLOCKED: '$NORM_PATH' is outside File Scope for ${TASK_LABEL}." >&2
  echo "Allowed paths: $ALLOWED_PATHS" >&2
  exit 2
else
  echo "WARNING: '$NORM_PATH' is outside File Scope for ${TASK_LABEL}." >&2
  echo "Allowed paths: $ALLOWED_PATHS" >&2
  exit 0
fi

__EOF_TMPL_HOOK_CHECK_SCOPE__

read -r -d '' TMPL_HOOK_SESSION_START <<'__EOF_TMPL_HOOK_SESSION_START__' || true
#!/usr/bin/env bash
# =============================================================================
# TASK-0039: session-start.sh
# Purpose:  SessionStart hook (no stdin) — display project context summary
# Profile:  minimal+ (runs for all profiles except "none")
# Behavior: Prints to stdout:
#           1. Latest 3 RUN logs from .sage/runs/ (status, task_id, error_log)
#           2. In-progress/blocked TASKs from tasks/*.md
#           3. Latest 5 entries from sage/failures.md
#           Always exit 0
# =============================================================================
set -euo pipefail

# --- Profile gating ---
PROFILE="minimal"
if [ -f ".sage/config.yaml" ]; then
  PROFILE=$(grep -A1 'hooks:' .sage/config.yaml 2>/dev/null | grep 'profile:' | awk '{print $2}' | tr -d '"' || echo "minimal")
  [ -z "$PROFILE" ] && PROFILE="minimal"
fi

# minimal+ means all profiles run this hook (minimal, standard, strict)
if [ "$PROFILE" = "none" ]; then
  exit 0
fi

task_status() {
  awk -F'|' '/^\|[[:space:]]*ステータス[[:space:]]*\|/ {gsub(/^[[:space:]]+|[[:space:]]+$/, "", $3); print $3; exit}' "$1" 2>/dev/null || true
}

echo "=== SAGE Session Context ==="
echo ""

# --- 0. Lane Detection ---
echo "--- Current Lane ---"
CURRENT_BRANCH=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo "unknown")
LANE="standard"
LANE_EMOJI="🔵"
LANE_DESC="Full SAGE lifecycle: SPEC + PLAN + TASK required. Gates 1-4."

if [[ "$CURRENT_BRANCH" == vibe/* ]]; then
  LANE="explore"
  LANE_EMOJI="🟢"
  LANE_DESC="Free exploration. No SPEC, no TASK-ID, no gates required. To promote: bash scripts/sage-promote.sh $CURRENT_BRANCH"
elif [[ "$CURRENT_BRANCH" == fix/* || "$CURRENT_BRANCH" == chore/* || "$CURRENT_BRANCH" == docs/* ]]; then
  LANE="lite"
  LANE_EMOJI="🟡"
  LANE_DESC="Lightweight changes. TASK-ID required, SPEC not required. Gates 1+3. Max 3 files, no contract changes."
elif [[ "$CURRENT_BRANCH" == promote/* ]]; then
  LANE="promotion"
  LANE_EMOJI="🔴"
  LANE_DESC="Promotion from explore. Retro-SPEC + TASK-ID required. Gates 1-4."
fi

echo "  Branch: $CURRENT_BRANCH"
echo "  Lane:   $LANE_EMOJI $LANE"
echo "  Rules:  $LANE_DESC"
echo ""

# --- 1. Latest 3 RUN logs ---
echo "--- Recent RUN Logs ---"
if [ -d ".sage/runs" ] && ls .sage/runs/*.json &>/dev/null 2>&1; then
  # Get latest 3 files by modification time
  LATEST_RUNS=$(ls -t .sage/runs/*.json 2>/dev/null | head -3)

  for run_file in $LATEST_RUNS; do
    [ -f "$run_file" ] || continue
    RUN_NAME=$(basename "$run_file")

    if command -v jq &>/dev/null; then
      STATUS=$(jq -r '.status // "unknown"' "$run_file" 2>/dev/null || echo "unknown")
      TASK_ID=$(jq -r '.task_id // "N/A"' "$run_file" 2>/dev/null || echo "N/A")
      ERROR_LOG=$(jq -r '.error_log // empty' "$run_file" 2>/dev/null | head -1 || true)
    else
      STATUS=$(grep -o '"status"[[:space:]]*:[[:space:]]*"[^"]*"' "$run_file" 2>/dev/null | head -1 | sed 's/.*"status"[[:space:]]*:[[:space:]]*"//;s/"$//' || echo "unknown")
      TASK_ID=$(grep -o '"task_id"[[:space:]]*:[[:space:]]*"[^"]*"' "$run_file" 2>/dev/null | head -1 | sed 's/.*"task_id"[[:space:]]*:[[:space:]]*"//;s/"$//' || echo "N/A")
      ERROR_LOG=$(grep -o '"error_log"[[:space:]]*:[[:space:]]*"[^"]*"' "$run_file" 2>/dev/null | head -1 | sed 's/.*"error_log"[[:space:]]*:[[:space:]]*"//;s/"$//' | head -1 || true)
    fi

    echo "  $RUN_NAME: status=$STATUS task=$TASK_ID${ERROR_LOG:+ error=$ERROR_LOG}"
  done
elif [ -d ".sage/runs" ] && ls .sage/runs/*.yaml &>/dev/null 2>&1; then
  LATEST_RUNS=$(ls -t .sage/runs/*.yaml 2>/dev/null | head -3)
  for run_file in $LATEST_RUNS; do
    [ -f "$run_file" ] || continue
    RUN_NAME=$(basename "$run_file")
    STATUS=$(grep 'status:' "$run_file" 2>/dev/null | head -1 | awk '{print $2}' || echo "unknown")
    TASK_ID=$(grep 'task_id:' "$run_file" 2>/dev/null | head -1 | awk '{print $2}' || echo "N/A")
    echo "  $RUN_NAME: status=$STATUS task=$TASK_ID"
  done
else
  echo "  No RUN logs found."
fi
echo ""

# --- 2. In-progress / Blocked TASKs ---
echo "--- Active TASKs ---"
FOUND_TASKS=false
if [ -d "tasks" ]; then
  for task_file in tasks/*.md; do
    [ -f "$task_file" ] || continue

    TASK_NAME=$(basename "$task_file" .md)

    STATUS=$(task_status "$task_file")
    case "$STATUS" in
      "In Progress"|"実行中")
        echo "  [$TASK_NAME] Status: In Progress"
        FOUND_TASKS=true
        ;;
      "Blocked"|"ブロック中")
        echo "  [$TASK_NAME] Status: Blocked"
        FOUND_TASKS=true
        ;;
    esac
  done
fi

if [ "$FOUND_TASKS" = false ]; then
  echo "  No active TASKs."
fi
echo ""

# --- 3. Latest 5 entries from sage/failures.md ---
echo "--- Recent Failures ---"
if [ -f "sage/failures.md" ]; then
  # Extract failure entries (lines starting with ## or ### as entry headers)
  # Show last 5 entry headers with their first detail line
  ENTRIES=$(grep -n '^##' "sage/failures.md" 2>/dev/null | tail -5)

  if [ -n "$ENTRIES" ]; then
    while IFS= read -r entry; do
      LINE_NUM=$(echo "$entry" | cut -d: -f1)
      HEADER=$(echo "$entry" | cut -d: -f2-)
      # Get next non-empty line as detail
      DETAIL=$(sed -n "$((LINE_NUM + 1)),$((LINE_NUM + 3))p" "sage/failures.md" 2>/dev/null | grep -v '^$' | head -1 || true)
      echo "  $HEADER"
      [ -n "$DETAIL" ] && echo "    $DETAIL"
    done <<< "$ENTRIES"
  else
    echo "  No failure entries found."
  fi
else
  echo "  sage/failures.md not found."
fi

echo ""
echo "=== End Session Context ==="

exit 0

__EOF_TMPL_HOOK_SESSION_START__

